// MOCK WhatsApp channel. No WhatsApp Business API is called and nothing leaves the device.
// The app shows these messages in a simulated "karigar phone". Planned: WhatsApp Business API
// sandbox or an IVR provider, with voice notes generated by real Indic TTS.
//
// Templates are fixed text, not machine translation. The Hindi wording was written for this
// prototype and MUST be checked by a native speaker and by real karigars before field use.

import { formatMg, formatFineUg, formatPaise, formatBp } from '../core/units.js';

export const IS_MOCK = true;
export const LABEL = 'MOCK WHATSAPP: simulated in-app, nothing is sent';

const T = {
  hi: {
    ISSUE: (p, x) => `${x.jeweller} से सोना मिला: ${p.gold.map((g) => `${formatMg(g.grossMg)} (${g.fineness})`).join(' + ')} = ${x.fine} शुद्ध। काम: ${p.design}। छीजत: ${formatBp(p.wastageBp)}। तारीख: ${p.dueDate}। सही है तो "हाँ" बोलिए, गलत है तो "नहीं"।`,
    RETURN: (p, x) => `आपने वापस दिया: ${p.pieces.length} पीस, ${p.scrap.length} भुका/स्क्रैप। ${x.fine} शुद्ध दर्ज हुआ। सही है तो "हाँ" बोलिए।`,
    SETTLEMENT: (p) => `हिसाब: मजदूरी ${formatPaise(p.cashBalancePaise)}, सोना बाकी ${formatFineUg(p.goldBalanceUg)} शुद्ध। सही है तो "हाँ" बोलिए।`,
    PAYMENT: (p) => `${formatPaise(p.amountPaise)} भेजे गए (${p.method === 'UPI_MOCK' ? 'नकली UPI, डेमो' : 'नकद'})। पैसे मिल गए तो "हाँ" बोलिए।`,
    OPENING_BALANCE: (p) => `पुराना हिसाब: सोना ${formatFineUg(p.goldUg)} शुद्ध, पैसे ${formatPaise(p.cashPaise)}। सही है तो "हाँ" बोलिए।`,
    REFINER_RESULT: (p) => `रिफाइनर से ${formatFineUg(p.recoveredFineUg)} शुद्ध सोना निकला। सही है तो "हाँ" बोलिए।`,
    VOID: (p) => `एक एंट्री रद्द करने का अनुरोध: ${p.reason}। मंज़ूर है तो "हाँ" बोलिए।`,
    DISPUTE_RESOLUTION: (p) => `झगड़े का निपटारा: ${p.note}। मंज़ूर है तो "हाँ" बोलिए।`,
    OPEN_ACCOUNT: (p) => `${p.parties.jeweller.name} आपके साथ सोने का साझा खाता खोलना चाहते हैं। आप अपना पूरा खाता हमेशा देख सकते हैं। ${p.consent.text} मंज़ूर है तो "हाँ" बोलिए।`,
    REMIND_DEADLINE: (_, x) => `${x.design} का काम कहाँ तक पहुँचा? तारीख ${x.dueDate} है। आवाज़ में बता दीजिए।`,
    CHASE_APPROVAL: (_, x) => `${x.count} एंट्री आपकी "हाँ" या "नहीं" का इंतज़ार कर रही हैं।`,
  },
  en: {
    ISSUE: (p, x) => `Gold received from ${x.jeweller}: ${p.gold.map((g) => `${formatMg(g.grossMg)} (${g.fineness})`).join(' + ')} = ${x.fine} fine. Work: ${p.design}. Wastage: ${formatBp(p.wastageBp)}. Due: ${p.dueDate}. Say "yes" if correct, "no" if not.`,
    RETURN: (p, x) => `You returned ${p.pieces.length} piece(s) and ${p.scrap.length} scrap lot(s), recorded as ${x.fine} fine. Say "yes" if correct.`,
    SETTLEMENT: (p) => `Settlement: labour ${formatPaise(p.cashBalancePaise)}, gold balance ${formatFineUg(p.goldBalanceUg)} fine. Say "yes" if correct.`,
    PAYMENT: (p) => `${formatPaise(p.amountPaise)} sent (${p.method === 'UPI_MOCK' ? 'MOCK UPI, demo only' : 'cash'}). Say "yes" once you have received it.`,
    OPENING_BALANCE: (p) => `Opening balance: gold ${formatFineUg(p.goldUg)} fine, cash ${formatPaise(p.cashPaise)}. Say "yes" if correct.`,
    REFINER_RESULT: (p) => `The refiner recovered ${formatFineUg(p.recoveredFineUg)} fine. Say "yes" if correct.`,
    VOID: (p) => `Request to cancel an entry: ${p.reason}. Say "yes" to agree.`,
    DISPUTE_RESOLUTION: (p) => `Proposed resolution: ${p.note}. Say "yes" to agree.`,
    OPEN_ACCOUNT: (p) => `${p.parties.jeweller.name} wants to open a shared gold account with you. You can always see your full account. ${p.consent.text} Say "yes" to agree.`,
    REMIND_DEADLINE: (_, x) => `How far along is ${x.design}? It is due ${x.dueDate}. Reply by voice.`,
    CHASE_APPROVAL: (_, x) => `${x.count} entr${x.count === 1 ? 'y is' : 'ies are'} waiting for your "yes" or "no".`,
  },
};

/** Build the message the karigar would receive for a ledger entry or agent action. */
export function messageFor(lang, kind, payload, extra = {}) {
  const t = (T[lang] ?? T.en)[kind] ?? T.en[kind];
  if (!t) return null;
  return { mock: true, lang, kind, text: t(payload ?? {}, extra) };
}
